import React from 'react';
import './PageTemplate.css';

const Promotion = () => {
  return (
    <div className="page-template">
      <h1 className="page-title">校外推广应用</h1>

      <div className="content-section">
        <h2>推广应用情况</h2>
        <p>
          本成果已在多所职业院校得到推广应用，
          形成了良好的示范效应和社会影响。
        </p>
      </div>
    </div>
  );
};

export default Promotion;
